-- =====================================================================
-- VISITA VIRTUAL v2 — escenas 360° y panorámicas para los 4 destinos
-- Ejecutar en Supabase > SQL Editor (después de visita_virtual.sql).
-- Se puede re-ejecutar: solo carga escenas en destinos que no tengan.
-- =====================================================================

alter table public.tour_scenes add column if not exists is_360 boolean not null default true;
alter table public.tour_scenes add column if not exists haov numeric(6,2);

do $$ begin
    alter table public.tour_scenes add constraint tour_scenes_haov_range check (haov is null or haov between 30 and 360);
exception when duplicate_object then null;
end $$;

-- Reemplaza la carga inicial antigua de Cusco (9 escenas sin Machu Picchu) por el recorrido completo.
delete from public.tour_scenes t
where t.credit = 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons'
  and t.destination_id in (select id from public.destinations where slug = 'cusco')
  and not exists (select 1 from public.tour_scenes m where m.destination_id = t.destination_id and m.title like 'Machu Picchu%');

-- Recorridos iniciales con fotos de licencia libre (Wikimedia Commons, con crédito al autor).
insert into public.tour_scenes (destination_id, sort_order, title, description, image_url, credit, credit_url, is_360, haov)
select d.id, v.sort_order, v.title, v.description, v.image_url, v.credit, v.credit_url, v.is_360, v.haov
from (values
    ('cusco', 1, 'Machu Picchu: vista clásica', 'La ciudadela inca con el Huayna Picchu al fondo.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/99_-_Machu_Picchu_-_Juin_2009.jpg/3840px-99_-_Machu_Picchu_-_Juin_2009.jpg', 'Martin St-Amant · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:99_-_Machu_Picchu_-_Juin_2009.jpg', false, 190),
    ('cusco', 2, 'Machu Picchu: panorámica', 'Terrazas, templos y plazas entre montañas y nubes.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Machu_Picchu_panorama.jpg/3840px-Machu_Picchu_panorama.jpg', 'Brian Jeffery Beggerly · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Machu_Picchu_panorama.jpg', false, 140),
    ('cusco', 3, 'Casa del Guardián y río Urubamba', 'El mirador más famoso, sobre el valle del Urubamba.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/1_pano_machu_picchu_guard_house_river_2014.jpg/3840px-1_pano_machu_picchu_guard_house_river_2014.jpg', 'Chensiyuan · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1_pano_machu_picchu_guard_house_river_2014.jpg', false, 110),
    ('cusco', 4, 'Plaza de Armas del Cusco', 'Corazón de la ciudad imperial, rodeada de portales coloniales.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Plaza_de_armas_del_Cusco%2C_vista_360.jpg/3840px-Plaza_de_armas_del_Cusco%2C_vista_360.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Plaza_de_armas_del_Cusco%2C_vista_360.jpg', true, null),
    ('cusco', 5, 'Catedral del Cusco', 'Joya del barroco andino construida sobre un palacio inca.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Actual_catedra%C4%BA_del_Cusco%2C_Plaza_de_armas.jpg/3840px-Actual_catedra%C4%BA_del_Cusco%2C_Plaza_de_armas.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Actual_catedra%C4%BA_del_Cusco%2C_Plaza_de_armas.jpg', true, null),
    ('cusco', 6, 'Iglesia de la Plaza', 'Templos coloniales que enmarcan la plaza principal.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Vista_360_plaza_del_Cusco%2C_Iglesia.jpg/3840px-Vista_360_plaza_del_Cusco%2C_Iglesia.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vista_360_plaza_del_Cusco%2C_Iglesia.jpg', true, null),
    ('cusco', 7, 'Calles de San Blas', 'Subida empedrada entre Tandapata y Kiskapata, junto al mirador.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Subida_entre_las_calles_Tandapata_y_Kiskapata%2C_al_lado_del_Mirador_de_San_Blas%2C_Cusco.jpg/3840px-Subida_entre_las_calles_Tandapata_y_Kiskapata%2C_al_lado_del_Mirador_de_San_Blas%2C_Cusco.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Subida_entre_las_calles_Tandapata_y_Kiskapata%2C_al_lado_del_Mirador_de_San_Blas%2C_Cusco.jpg', true, null),
    ('cusco', 8, 'Vista de la ciudad', 'Panorámica de los techos de teja del Cusco.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Ciudad_del_cusco_vista_360.jpg/3840px-Ciudad_del_cusco_vista_360.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ciudad_del_cusco_vista_360.jpg', true, null),
    ('cusco', 9, 'Kusilluchayuq (Templo de los Monos)', 'Huaca inca tallada en la roca, a las afueras de la ciudad.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Kusilluchayuq%2C_Cusco%2C_360.jpg/3840px-Kusilluchayuq%2C_Cusco%2C_360.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kusilluchayuq%2C_Cusco%2C_360.jpg', true, null),
    ('cusco', 10, 'Huaca de la Luna', 'Santuario inca de piedra rodeado de campiña andina.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Huaca_de_la_Luna%2C_Cusco%2C_360.jpg/3840px-Huaca_de_la_Luna%2C_Cusco%2C_360.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Huaca_de_la_Luna%2C_Cusco%2C_360.jpg', true, null),
    ('cusco', 11, 'Camino Inca al Antisuyu', 'Tramo original del Qhapaq Ñan que salía del Cusco.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Camino_Inca_al_Antisuyu_360.jpg/3840px-Camino_Inca_al_Antisuyu_360.jpg', 'Johnattan Rupire · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Camino_Inca_al_Antisuyu_360.jpg', true, null),
    ('arequipa', 1, 'Volcanes de Arequipa', 'El Misti, el Chachani y el Pichu Pichu custodian la Ciudad Blanca.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Panor%C3%A1mica_cerca_de_Arequipa%2C_Per%C3%BA%2C_2015-08-02%2C_DD_04-07_PAN.JPG/3840px-Panor%C3%A1mica_cerca_de_Arequipa%2C_Per%C3%BA%2C_2015-08-02%2C_DD_04-07_PAN.JPG', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Panor%C3%A1mica_cerca_de_Arequipa%2C_Per%C3%BA%2C_2015-08-02%2C_DD_04-07_PAN.JPG', false, 180),
    ('arequipa', 2, 'Cañón del Colca', 'Uno de los cañones más profundos del mundo.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Colca_Canyon_Panorama.jpg/3840px-Colca_Canyon_Panorama.jpg', 'Ivan Mlinaric · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Colca_Canyon_Panorama.jpg', false, 190),
    ('arequipa', 3, 'Valle del Colca', 'Andenes preincas que siguen cultivándose hoy.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Colca_Valley_Panorama.jpg/3840px-Colca_Valley_Panorama.jpg', 'Ivan Mlinaric · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Colca_Valley_Panorama.jpg', false, 170),
    ('arequipa', 4, 'Mirador del Colca', 'Vista de casi 360° desde el borde del cañón.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Colca_canyon_panorama.jpg/3840px-Colca_canyon_panorama.jpg', 'Cédric Liénart · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Colca_canyon_panorama.jpg', false, 340),
    ('ica', 1, 'Oasis de Huacachina', 'Laguna rodeada de palmeras y dunas gigantes.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Vista_panor%C3%A0mica_de_Huacachina.jpg/3840px-Vista_panor%C3%A0mica_de_Huacachina.jpg', 'Pitxiquin · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vista_panor%C3%A0mica_de_Huacachina.jpg', false, 200),
    ('ica', 2, 'Huacachina desde las dunas', 'Punto de partida de los tubulares y el sandboard.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Huacachina_Oasis_Panorama.JPG/3840px-Huacachina_Oasis_Panorama.JPG', 'Kob123456 · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Huacachina_Oasis_Panorama.JPG', false, 140),
    ('ica', 3, 'Desierto de Paracas', 'La reserva donde el desierto se encuentra con el océano.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Paracas_-_pou%C5%A1%C5%A5_-_panoramio.jpg/3840px-Paracas_-_pou%C5%A1%C5%A5_-_panoramio.jpg', 'Pavel Špindler · CC BY 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paracas_-_pou%C5%A1%C5%A5_-_panoramio.jpg', false, 130),
    ('ica', 4, 'Islas Ballestas', 'Lobos marinos, pingüinos de Humboldt y aves guaneras.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Ballestas_Islands_P%C3%A9rou_2011.jpg/3840px-Ballestas_Islands_P%C3%A9rou_2011.jpg', 'Pierre André Leclercq · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ballestas_Islands_P%C3%A9rou_2011.jpg', false, 115),
    ('puno', 2, 'Puno y el lago Titicaca', 'La ciudad junto al lago navegable más alto del mundo.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Vista_de_Puno_y_el_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_64-72_PAN.JPG/3840px-Vista_de_Puno_y_el_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_64-72_PAN.JPG', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vista_de_Puno_y_el_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_64-72_PAN.JPG', false, 360),
    ('puno', 1, 'Islas flotantes de los Uros', 'Islas construidas a mano con totora.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_44-48_PAN.jpg/3840px-Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_44-48_PAN.jpg', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_44-48_PAN.jpg', false, 220),
    ('puno', 3, 'Vida en los Uros', 'Casas y botes tradicionales de totora.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_19.JPG/3840px-Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_19.JPG', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_19.JPG', false, 110),
    ('puno', 4, 'Amanecer en el Titicaca', 'El sol nace sobre el lago sagrado de los incas.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Amanecer_en_el_lago_Titicaca%2C_Puno%2C_Per%C3%BA%2C_2015-08-01%2C_DD_01.JPG/3840px-Amanecer_en_el_lago_Titicaca%2C_Puno%2C_Per%C3%BA%2C_2015-08-01%2C_DD_01.JPG', 'Diego Delso · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amanecer_en_el_lago_Titicaca%2C_Puno%2C_Per%C3%BA%2C_2015-08-01%2C_DD_01.JPG', false, 100)
) as v(slug, sort_order, title, description, image_url, credit, credit_url, is_360, haov)
join public.destinations d on d.slug = v.slug
where not exists (select 1 from public.tour_scenes t where t.destination_id = d.id);

-- Fotos reales de licencia libre para las tarjetas de destinos (antes había imágenes que no correspondían).
update public.destinations set image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Colca_Valley_Panorama.jpg/1280px-Colca_Valley_Panorama.jpg', image_path = null where slug = 'arequipa' and (image_url like 'https://images.unsplash.com/%' or image_url is null);
update public.destinations set image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Vista_panor%C3%A0mica_de_Huacachina.jpg/1280px-Vista_panor%C3%A0mica_de_Huacachina.jpg', image_path = null where slug = 'ica' and (image_url like 'https://images.unsplash.com/%' or image_url is null);
update public.destinations set image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_44-48_PAN.jpg/1280px-Islas_flotantes_de_los_Uros%2C_Lago_Titicaca%2C_Per%C3%BA%2C_2015-08-01%2C_DD_44-48_PAN.jpg', image_path = null where slug = 'puno' and (image_url like 'https://images.unsplash.com/%' or image_url is null);
